(()=>{
 const id=document.querySelector('meta[name="ga-measurement-id"]')?.content;if(!/^G-[A-Z0-9]+$/.test(id||''))return;
 let loaded=false;const get=()=>{try{return localStorage.getItem('psb-analytics-consent')}catch{return null}};
 const activate=()=>{if(loaded)return;loaded=true;window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments)};gtag('consent','default',{analytics_storage:'granted',ad_storage:'denied',ad_user_data:'denied',ad_personalization:'denied'});gtag('js',new Date());gtag('config',id,{send_page_view:false,allow_google_signals:false,allow_ad_personalization_signals:false});gtag('event','page_view',{page_title:document.title,page_location:location.origin+location.pathname,page_referrer:document.referrer?new URL(document.referrer).origin:''});const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtag/js?id='+encodeURIComponent(id);document.head.append(script);try{if(location.pathname==='/thank-you/'&&sessionStorage.getItem('psb-enquiry-sent')==='1'){gtag('event','generate_lead');sessionStorage.removeItem('psb-enquiry-sent');}}catch{}};
 const banner=document.createElement('aside');banner.className='analytics-choice';banner.setAttribute('aria-label','Analytics preference');banner.innerHTML='<p>Allow anonymous usage measurement to help improve this website? <a href="/privacy/">Privacy policy</a></p><div><button type="button" data-choice="granted">Allow analytics</button><button type="button" data-choice="denied">Decline</button></div>';document.body.append(banner);
 const show=()=>{banner.hidden=false;};banner.hidden=!!get();if(get()==='granted')activate();
 banner.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>{const choice=button.dataset.choice;try{localStorage.setItem('psb-analytics-consent',choice)}catch{}banner.hidden=true;if(choice==='granted')activate();else if(loaded){window['ga-disable-'+id]=true;gtag('consent','update',{analytics_storage:'denied'});for(const cookie of document.cookie.split(';')){const name=cookie.trim().split('=')[0];if(name.startsWith('_ga')){document.cookie=name+'=; Max-Age=0; path=/';const parts=location.hostname.split('.');for(let i=0;i<parts.length-1;i++)document.cookie=name+'=; Max-Age=0; path=/; domain=.'+parts.slice(i).join('.');}}location.reload();}}));
 const footer=document.querySelector('.footer-bottom');if(footer){const button=document.createElement('button');button.type='button';button.className='analytics-settings';button.textContent='Analytics preferences';button.addEventListener('click',show);footer.append(button);}
})();
